# owner: platform
"""Find the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.merging import merge_spans
from hourglass.errors import ProjectError


def _clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"


# ---
def find_gaps(
    worked: Iterable[Span], hours: Span
) -> List[str]:
    """One label per uncovered stretch.

    Looks like "gap 12:00-13:00 (60 min)". Raises
    ProjectError if a span leaves opening hours.
    """
    spans = list(worked)
    for span in spans:
        if span.start < hours.start or (
            span.end > hours.end
        ):
            first = _clock(span.start)
            last = _clock(span.end)
            raise ProjectError(
                f"span {first}-{last} is outside"
                " opening hours"
            )

    labels = []
    cursor = hours.start
    for span in merge_spans(spans):
        if span.start > cursor:
            labels.append(_label(cursor, span.start))
        cursor = span.end
    if cursor < hours.end:
        labels.append(_label(cursor, hours.end))
    return labels


def _label(start: int, end: int) -> str:
    length = end - start
    return (
        f"gap {_clock(start)}-{_clock(end)}"
        f" ({length} min)"
    )
